import{_ as l,a0 as s,w as i,s as d,ao as u,I as p,x as e,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"什麼是邏輯分區管理 LVM ，如何在Ubuntu中使用？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是邏輯分區管理 LVM ，如何在Ubuntu中使用？ | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是邏輯分區管理 LVM ，如何在Ubuntu中使用？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是邏輯分區管理 LVM ，如何在Ubuntu中使用？ | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150729 What is Logical Volume Management and How Do You Enable It in Ubuntu","title":"什麼是邏輯分區管理 LVM ，如何在Ubuntu中使用？","tag":"201508","desc":""},"relativePath":"201508/20150729 What is Logical Volume Management and How Do You Enable It in Ubuntu.md","filePath":"[post].md"}'),r={name:"201508/20150729 What is Logical Volume Management and How Do You Enable It in Ubuntu.md"};function m(g,t,b,L,w,V){const o=s("Link");return i(),d("div",null,[t[16]||(t[16]=u('<h1 id="什麼是邏輯分區管理-lvm-如何在ubuntu中使用" tabindex="-1">什麼是邏輯分區管理 LVM ，如何在Ubuntu中使用？ <a class="header-anchor" href="#什麼是邏輯分區管理-lvm-如何在ubuntu中使用" aria-label="Permalink to “什麼是邏輯分區管理 LVM ，如何在Ubuntu中使用？”">​</a></h1><blockquote><p>邏輯分區管理（LVM）是每一個主流Linux發行版都含有的磁盤管理選項。無論是你需要設置存儲池，還是隻想動態創建分區，那麼LVM就是你正在尋找的。</p></blockquote><h3 id="什麼是-lvm" tabindex="-1">什麼是 LVM? <a class="header-anchor" href="#什麼是-lvm" aria-label="Permalink to “什麼是 LVM?”">​</a></h3><p>邏輯分區管理是一個存在於磁盤/分區和操作系統之間的一個抽象層。在傳統的磁盤管理中，你的操作系統尋找有哪些磁盤可用（/dev/sda、/dev/sdb等等），並且這些磁盤有哪些可用的分區（如/dev/sda1、/dev/sda2等等）。</p><p>在LVM下，磁盤和分區可以抽象成一個含有多個磁盤和分區的設備。你的操作系統將不會知道這些區別，因為LVM只會給操作系統展示你設置的卷組（磁盤）和邏輯卷（分區）</p><p>因為卷組和邏輯卷並不物理地對應到影片，因此可以很容易地動態調整和創建新的磁盤和分區。除此之外，LVM帶來了你的文件系統所不具備的功能。比如，ext3不支持實時快照，但是如果你正在使用LVM你可以不卸載磁盤的情況下做一個邏輯卷的快照。</p><h3 id="你什麼時候該使用lvm" tabindex="-1">你什麼時候該使用LVM？ <a class="header-anchor" href="#你什麼時候該使用lvm" aria-label="Permalink to “你什麼時候該使用LVM？”">​</a></h3><p>在使用LVM之前首先得考慮的一件事是你要用你的磁盤和分區來做什麼。注意，一些發行版如Fedora已經默認安裝了LVM。</p><p>如果你使用的是一台只有一塊磁盤的Ubuntu筆記本電腦，並且你不需要像實時快照這樣的擴展功能，那麼你或許不需要LVM。如果你想要輕鬆地擴展或者想要將多塊磁盤組成一個存儲池，那麼LVM或許正是你所尋找的。</p><h3 id="在ubuntu中設置lvm" tabindex="-1">在Ubuntu中設置LVM <a class="header-anchor" href="#在ubuntu中設置lvm" aria-label="Permalink to “在Ubuntu中設置LVM”">​</a></h3><p>使用LVM首先要了解的一件事是，沒有一個簡單的方法可以將已有的傳統分區轉換成邏輯卷。可以將數據移到一個使用LVM的新分區下，但是這並不會在本篇中提到；在這裏，我們將全新安裝一台Ubuntu 10.10來設置LVM。（LCTT 譯註：本文針對的是較老的版本，新的版本已經不需如此麻煩了）</p>',11)),p("p",null,[t[1]||(t[1]=e("要使用LVM安裝Ubuntu你需要使用另外的安裝CD。從下面的鏈接中下載並燒錄到CD中或者",-1)),n(o,{href:"http://www.howtogeek.com/howto/13379/create-a-bootable-ubuntu-9.10-usb-flash-drive/"},{default:a(()=>[...t[0]||(t[0]=[e("使用unetbootin創建一個USB盤",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[17]||(t[17]=u('<p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2010/12/download-web.png" alt=""></p><p>從安裝盤啓動你的電腦，並在磁盤選擇界面選擇整個磁盤並設置LVM。</p><p><em>注意：這會格式化你的整個磁盤，因此如果正在嘗試雙啓動或者其他的安裝選擇，選擇手動。</em></p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2010/12/setup-1.png" alt=""></p><p>選擇你想用的主磁盤，最典型的是使用你最大的磁盤，接着進入下一步。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2010/12/setup-2.png" alt=""></p><p>你馬上會將改變寫入磁盤所以確保此時你選擇的是正確的磁盤接着才寫入設置。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2010/12/setup-3.png" alt=""></p><p>選擇第一個邏輯卷的大小並繼續。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2011/01/setup-4.png" alt=""></p><p>確認你的磁盤分區並繼續安裝。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2011/01/setup-5.png" alt=""></p><p>最後一步將GRUB的bootloader寫到磁盤中。重點注意的是GRUB不能作為一個LVM分區因為計算機BIOS不能直接從邏輯卷中讀取數據。Ubuntu將自動創建一個255MB的ext2分區用於bootloder。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2011/01/setup-6.png" alt=""></p><p>安裝完成之後。重啓電腦並如往常一樣進入Ubuntu。使用這種方式安裝之後應該就感受不到LVM和傳統磁盤管理之間的區別了。</p><p><img src="http://cdn3.howtogeek.com/wp-content/uploads/2011/01/disk-manager.png" alt=""></p><p>要使用LVM的全部功能，靜待我們的下篇關於管理LVM的文章。</p><hr>',18)),p("p",null,[t[4]||(t[4]=e("via: ",-1)),n(o,{href:"http://www.howtogeek.com/howto/36568/what-is-logical-volume-management-and-how-do-you-enable-it-in-ubuntu/"},{default:a(()=>[...t[3]||(t[3]=[e("http://www.howtogeek.com/howto/36568/what-is-logical-volume-management-and-how-do-you-enable-it-in-ubuntu/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("作者：",-1)),n(o,{href:"https://plus.google.com/+howtogeek?prsrc=5"},{default:a(()=>[...t[5]||(t[5]=[e("How-To Geek",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:a(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),n(o,{href:"https://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const f=l(r,[["render",m]]);export{T as __pageData,f as default};
